out=[]
for i,q in enumerate(d):
    est,prop,conf,mot,exp,src=R[i]
    code=q['codes'][0]
    cod=code.split(' ')[0]
    tema=code[code.find('[')+1:code.find(':')] if '[' in code else ''
    esp='Neumologia' if tema.startswith('resp') or tema.startswith('infecto') else ('Cardiologia' if tema.startswith('cardio') else 'Otorrino' if tema.startswith('orl') else '')
    f=lambda s:s.replace(';',',').replace('\n',' ')
    out.append([f(q['recTag']),q['year'],cod,esp,est,q['correcta'],prop,conf,f(mot),f(exp),f(src or code[code.find('[')+1:code.find(']')])])
with open('out9.csv','w',newline='') as fh:
    csv.writer(fh,delimiter=';').writerows(out)
from collections import Counter
print(len(out),Counter(o[4] for o in out))
